// Generated by exit-ramp. Converts a Cloudflare Email Worker message into the shape Val Town email vals receive.
// Needs the `postal-mime` package (added to package.json). Route the address to this Worker in Email Routing:
// https://developers.cloudflare.com/email-routing/email-workers/
import PostalMime from "postal-mime";

export interface ValTownEmail {
  from: string;
  to: string[];
  cc: string | string[] | undefined;
  bcc: string | string[] | undefined;
  subject: string | undefined;
  text: string | undefined;
  html: string | undefined;
  attachments: File[];
  headers: Record<string, string>;
}

export async function toValTownEmail(message: ForwardableEmailMessage): Promise<ValTownEmail> {
  const parsed = await PostalMime.parse(message.raw);
  const headers: Record<string, string> = {};
  for (const h of parsed.headers) headers[h.key] = h.value;
  const addrs = (list: { address?: string }[] | undefined) => (list ?? []).map((a) => a.address ?? "").filter(Boolean);
  const cc = addrs(parsed.cc);
  const bcc = addrs(parsed.bcc);
  return {
    from: message.from,
    to: [message.to],
    cc: cc.length ? cc : undefined,
    bcc: bcc.length ? bcc : undefined,
    subject: parsed.subject,
    text: parsed.text,
    html: parsed.html,
    attachments: parsed.attachments.map((a) => new File([a.content as ArrayBuffer], a.filename ?? "attachment", { type: a.mimeType })),
    headers,
  };
}
